from __future__ import annotations

"""Apply Phase 21 v2 freshness alias cleanup."""

from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "tools" / "phase21_freshness_report.py"

NEW_CONTENT = 'from __future__ import annotations\n\n"""Phase 21 freshness report for the MLB app data pipeline.\n\nPhase 21 v2 makes the report alias-aware. The runtime API and Playerboard rows use\nboth snake_case and camelCase names (for example american_odds/americanOdds and\nsportsbook_count/bookCount). Freshness should validate the real data contract\nwithout reporting false missing fields just because a different casing is used.\n"""\n\nimport argparse\nimport csv\nimport glob\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\nROOT = Path(__file__).resolve().parents[1]\nDATA = ROOT / "data"\nAUDIT_DIR = DATA / "warehouse" / "audits"\n\nFIELD_ALIASES: dict[str, list[str]] = {\n    "player": ["player", "playerName", "name"],\n    "market": ["market", "baseMarket", "originalMarket", "marketDisplay"],\n    "team": ["team", "teamAbbr", "homeTeam", "awayTeam"],\n    "opponent": ["opponent", "opp", "opponentAbbr"],\n    "american_odds": ["american_odds", "americanOdds", "odds", "price", "best_american_odds", "bestAmericanOdds"],\n    "sportsbook_count": ["sportsbook_count", "sportsbookCount", "book_count", "bookCount"],\n    "best_book": ["best_book", "bestBook", "book", "sportsbook", "bookmaker", "bookmakerTitle"],\n    "team_moneyline": ["team_moneyline", "teamMoneyline"],\n    "opponent_moneyline": ["opponent_moneyline", "opponentMoneyline"],\n    "game_total": ["game_total", "gameTotal"],\n    "moneyline_implied_probability": ["moneyline_implied_probability", "moneylineImpliedProbability"],\n    "team_implied_runs": ["team_implied_runs", "teamImpliedRuns"],\n    "opponent_implied_runs": ["opponent_implied_runs", "opponentImpliedRuns"],\n    "weather_temperature_f": ["weather_temperature_f", "weatherTemperatureF", "temperature_f", "temperatureF"],\n    "weather_wind_mph": ["weather_wind_mph", "weatherWindMph", "wind_mph", "windMph"],\n    "weather_humidity": ["weather_humidity", "weatherHumidity", "humidity"],\n    "weather_wind_direction": ["weather_wind_direction", "weatherWindDirection", "wind_direction", "windDirection"],\n    "roof_status": ["roof_status", "roofStatus"],\n    "open_team_moneyline": ["open_team_moneyline", "openTeamMoneyline"],\n    "moneyline_move": ["moneyline_move", "moneylineMove"],\n    "open_game_total": ["open_game_total", "openGameTotal"],\n    "total_move": ["total_move", "totalMove"],\n}\n\n\ndef now_iso() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef clean(value: Any) -> str:\n    return str(value or "").strip()\n\n\ndef read_csv(path: Path) -> list[dict[str, str]]:\n    if not path.exists():\n        return []\n    with path.open("r", encoding="utf-8-sig", newline="") as handle:\n        return [dict(row) for row in csv.DictReader(handle)]\n\n\ndef read_json(path: Path, default: Any = None) -> Any:\n    if not path.exists():\n        return default\n    try:\n        return json.loads(path.read_text(encoding="utf-8"))\n    except Exception:\n        return default\n\n\ndef file_status(label: str, path: Path, *, required: bool = True) -> dict[str, Any]:\n    if not path.exists():\n        return {\n            "label": label,\n            "path": str(path),\n            "exists": False,\n            "required": required,\n            "status": "missing" if required else "optional_missing",\n        }\n    stat = path.stat()\n    modified = datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc)\n    age_seconds = max(0.0, (datetime.now(timezone.utc) - modified).total_seconds())\n    return {\n        "label": label,\n        "path": str(path),\n        "exists": True,\n        "required": required,\n        "status": "ok",\n        "sizeBytes": stat.st_size,\n        "modifiedAt": modified.isoformat(),\n        "ageSeconds": round(age_seconds, 3),\n    }\n\n\ndef newest_matching_status(label: str, pattern: str, *, required: bool = False) -> dict[str, Any]:\n    matches = sorted(\n        glob.glob(pattern),\n        key=lambda name: Path(name).stat().st_mtime if Path(name).exists() else 0,\n        reverse=True,\n    )\n    if not matches:\n        return {\n            "label": label,\n            "path": pattern,\n            "exists": False,\n            "required": required,\n            "status": "missing" if required else "optional_absent",\n        }\n    status = file_status(label, Path(matches[0]), required=required)\n    status["matchedPattern"] = pattern\n    return status\n\n\ndef aliases_for(field: str) -> list[str]:\n    aliases = FIELD_ALIASES.get(field, [field])\n    out: list[str] = []\n    for alias in [field, *aliases]:\n        if alias not in out:\n            out.append(alias)\n    return out\n\n\ndef row_value(row: dict[str, Any], field: str) -> str:\n    for alias in aliases_for(field):\n        value = row.get(alias)\n        if clean(value):\n            return clean(value)\n    return ""\n\n\ndef non_empty_count(rows: list[dict[str, Any]], field: str) -> int:\n    return sum(1 for row in rows if row_value(row, field))\n\n\ndef coverage(rows: list[dict[str, Any]], fields: list[str]) -> dict[str, Any]:\n    total = len(rows)\n    items = []\n    for field in fields:\n        count = non_empty_count(rows, field)\n        items.append({\n            "field": field,\n            "aliases": aliases_for(field),\n            "presentRows": count,\n            "coverage": round(count / max(1, total), 4),\n        })\n    return {"rows": total, "fields": items}\n\n\ndef coverage_lookup(payload: dict[str, Any], field: str) -> float:\n    for item in payload.get("fields", []):\n        if item.get("field") == field:\n            return float(item.get("coverage") or 0)\n    return 0.0\n\n\ndef build_report(date_label: str, season: int, *, write: bool = False) -> dict[str, Any]:\n    audit_dir = DATA / "warehouse" / "audits"\n    files = [\n        file_status("PropLine props", DATA / "odds" / f"propline_props_{date_label}.csv"),\n        file_status("Game context", DATA / "warehouse" / "game_context" / f"game_context_{date_label}.csv"),\n        file_status("Game context markets", DATA / "warehouse" / "game_context" / f"game_context_markets_{date_label}.csv"),\n        file_status("Phase 18 weather", DATA / "warehouse" / "game_context" / f"weather_phase18_{date_label}.json"),\n        file_status("Line movement snapshots", DATA / "warehouse" / "game_context" / "line_snapshots" / f"game_line_snapshots_{date_label}.csv", required=False),\n        file_status("Playerboard", DATA / "playerboard" / f"playerboard_{season}.csv"),\n        file_status("Phase 17 context audit", audit_dir / f"phase17_game_context_audit_{season}_{date_label}.json", required=False),\n        newest_matching_status(\n            "Latest Phase 21 daily report",\n            str(audit_dir / f"phase21_daily_refresh_{date_label}_*.json"),\n            required=False,\n        ),\n    ]\n\n    context_path = DATA / "warehouse" / "game_context" / f"game_context_{date_label}.csv"\n    context_rows = read_csv(context_path)\n    context_coverage = coverage(context_rows, [\n        "team_moneyline",\n        "opponent_moneyline",\n        "game_total",\n        "moneyline_implied_probability",\n        "team_implied_runs",\n        "opponent_implied_runs",\n        "weather_temperature_f",\n        "weather_wind_mph",\n        "weather_humidity",\n        "weather_wind_direction",\n        "roof_status",\n        "open_team_moneyline",\n        "moneyline_move",\n        "open_game_total",\n        "total_move",\n    ])\n\n    playerboard_rows = [\n        row for row in read_csv(DATA / "playerboard" / f"playerboard_{season}.csv")\n        if clean(row.get("date")) == date_label\n    ]\n    playerboard_core_coverage = coverage(playerboard_rows, [\n        "player",\n        "market",\n        "team",\n        "opponent",\n        "american_odds",\n        "sportsbook_count",\n        "best_book",\n    ])\n\n    missing_required = [item for item in files if item["required"] and not item["exists"]]\n    critical_context_missing = [\n        item["field"] for item in context_coverage["fields"]\n        if item["field"] in {\n            "team_moneyline",\n            "opponent_moneyline",\n            "game_total",\n            "team_implied_runs",\n            "opponent_implied_runs",\n            "weather_temperature_f",\n            "weather_wind_mph",\n        }\n        and item["coverage"] == 0\n    ]\n    critical_playerboard_missing = [\n        item["field"] for item in playerboard_core_coverage["fields"]\n        if item["field"] in {"player", "market", "team", "opponent", "american_odds"}\n        and item["coverage"] == 0\n    ]\n\n    movement_fields = {"open_team_moneyline", "moneyline_move", "open_game_total", "total_move"}\n    movement_status = "ready"\n    if any(coverage_lookup(context_coverage, field) == 0 for field in movement_fields):\n        movement_status = "pending_or_single_snapshot"\n\n    report = {\n        "status": "ok" if not missing_required and not critical_context_missing and not critical_playerboard_missing else "warning",\n        "date": date_label,\n        "season": season,\n        "generatedAt": now_iso(),\n        "files": files,\n        "contextCoverage": context_coverage,\n        "playerboardCoreCoverage": playerboard_core_coverage,\n        "movementStatus": movement_status,\n        "missingRequiredFiles": [item["label"] for item in missing_required],\n        "criticalContextMissing": critical_context_missing,\n        "criticalPlayerboardMissing": critical_playerboard_missing,\n        "notes": [\n            "Playerboard context fields are intentionally joined from canonical game_context in EdgeBoard; this report validates that source separately.",\n            "Opening-line movement can remain pending until multiple same-day snapshots or an opening-line provider are available.",\n            "OddsPapi is optional for Phase 21; PropLine/Open-Meteo/local references drive current game context.",\n        ],\n    }\n    if write:\n        AUDIT_DIR.mkdir(parents=True, exist_ok=True)\n        (AUDIT_DIR / f"phase21_freshness_{date_label}.json").write_text(\n            json.dumps(report, indent=2, ensure_ascii=False) + "\\n",\n            encoding="utf-8",\n        )\n    return report\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description="Build Phase 21 data freshness report.")\n    parser.add_argument("--date", required=True)\n    parser.add_argument("--season", type=int, default=2026)\n    parser.add_argument("--write", action="store_true")\n    args = parser.parse_args()\n    print(json.dumps(build_report(args.date, args.season, write=args.write), indent=2, ensure_ascii=False))\n\n\nif __name__ == "__main__":\n    main()\n'


def main() -> None:
    if not TARGET.exists():
        raise SystemExit(f"Missing expected file: {TARGET}")
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    backup = TARGET.with_suffix(TARGET.suffix + f".phase21v2_backup_{timestamp}")
    backup.write_text(TARGET.read_text(encoding="utf-8"), encoding="utf-8")
    TARGET.write_text(NEW_CONTENT, encoding="utf-8")
    print({
        "status": "ok",
        "changed": True,
        "path": str(TARGET),
        "backup": str(backup),
        "reason": "Phase 21 v2 freshness report now uses field aliases and avoids false optional_missing daily report noise.",
    })


if __name__ == "__main__":
    main()
